package edu.pe.cibertec.saibm.membresia;
import static org.assertj.core.api.Assertions.*; import java.nio.file.*; import org.junit.jupiter.api.Test;
 class InfrastructureContractTest { @Test void boundarySchemaAndFutureConsumerContractAreExplicit() throws Exception {var root=Path.of("src/main");try(var fs=Files.walk(root.resolve("java/edu/pe/cibertec/saibm/membresia/domain"))){fs.filter(p->p.toString().endsWith(".java")).forEach(p->{try{assertThat(Files.readString(p)).doesNotContain("org.springframework","jakarta.persistence");}catch(Exception e){throw new RuntimeException(e);}});}assertThat(Files.readString(root.resolve("java/edu/pe/cibertec/saibm/membresia/application/port/in/MembershipUseCase.java"))).doesNotContain("port.out");var sql=Files.readString(root.resolve("resources/db/migration/V1__membresia.sql"));assertThat(sql).contains("membership_plans","membership_assignments","membership_history","membership_outbox").doesNotContain("references");var y=Files.readString(root.resolve("resources/application.yml"));assertThat(y).contains("name: membresia-service","ddl-auto: validate","probes:","rabbitmq:","backfill:","enabled: ${SAIBM_MEMBRESIA_BACKFILL_ENABLED:false}");assertThat(Files.readString(root.resolve("java/edu/pe/cibertec/saibm/membresia/domain/event/MembershipEventType.java"))).contains("MembershipAssigned.v1","MembershipChanged.v1","MembershipExpired.v1","PlanUpdated.v1");assertThat(Files.readString(root.resolve("java/edu/pe/cibertec/saibm/membresia/infrastructure/messaging/UserDeactivatedContract.java"))).contains("UserDeactivated");}}
